def transform(grid):
    # Collapse adjacent identical rows.
    rows = []
    for row in grid:
        if not rows or row != rows[-1]:
            rows.append(row[:])

    # Collapse adjacent identical columns in the resulting grid.
    keep = []
    previous = None
    for c in range(len(rows[0])):
        column = tuple(row[c] for row in rows)
        if column != previous:
            keep.append(c)
            previous = column

    return [[row[c] for c in keep] for row in rows]
